(6, 1, '2026-08-14 13:44:03', '2026-08-14 13:44:03', '<!-- wp:paragraph -->\n<p>Welcome to CampusConnect<br>CampusConnect is a student information website that helps students discover campus activities, useful<br>resources, and student lifestyle tips.<br>Stay connected and make the most of your campus experience.<br>Explore Campus Life</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Campus activities</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Student events</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Study tips</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"http://localhost/wp_campusconnect/wordpress/index.php/sample-page/\" data-type=\"page\" data-id=\"2\">Student Resources</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":22,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/wp_campusconnect/wordpress/wp-content/uploads/2026/08/poster.png\" alt=\"\" class=\"wp-image-22\"/></figure>\n<!-- /wp:image -->', 'Home', '', 'publish', 'closed', 'closed', '', 'blog', '', '', '2026-08-14 13:59:10', '2026-08-14 13:59:10', '', 0, 'http://localhost/wp_campusconnect/wordpress/?page_id=6', 0, 'page', '', 0),
