(30, 1, '2026-08-14 14:24:45', '2026-08-14 14:24:45', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\" style=\"margin-top:var(--wp--preset--spacing--60)\"><!-- wp:heading {\"level\":1,\"metadata\":{\"patternName\":\"twentytwentyfive/hidden-blog-heading\",\"name\":\"Hidden blog heading\",\"description\":\"Hidden heading for the home page and index template.\"},\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<h1 class=\"wp-block-heading has-text-align-left\">Blog</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Campus Innovation Day provides students with an opportunity to showcase creative projects, digital solutions,<br>and innovative ideas.<br>Event Highlights</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Campus Innovation Day 2026.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Student project exhibition</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technology demonstrations</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Innovation competition</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Networking activities</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Managing your time effectively can help you complete your academic tasks and reduce unnecessary stress.<br>Time Management Tips</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>5 Simple Tips for Better Time Management.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Create a weekly schedule.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Prioritize important tasks.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Avoid unnecessary distractions.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Break large tasks into smaller tasks.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Review your progress regularly.</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></main>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"twentytwentyfive\"} /-->', 'Blog Home', 'Displays the latest posts as either the site homepage or as the \"Posts page\" as defined under reading settings. If it exists, the Front Page template overrides this template when posts are shown on the homepage.', 'inherit', 'closed', 'closed', '', '9-revision-v1', '', '', '2026-08-14 14:24:45', '2026-08-14 14:24:45', '', 9, 'http://localhost/wp_campusconnect/wordpress/?p=30', 0, 'revision', '', 0);

