(28, 1, '2026-08-01 15:44:26', '2026-08-01 15:44:26', '<!-- wp:cover {\"url\":\"http://localhost/wordpress/wp-content/uploads/2026/08/csr3.png\",\"id\":10,\"dimRatio\":10,\"isUserOverlayColor\":true,\"minHeight\":840,\"minHeightUnit\":\"px\",\"contentPosition\":\"bottom center\",\"isDark\":false,\"sizeSlug\":\"full\",\"metadata\":{\"patternName\":\"twentytwentyfive/hero-full-width-image\",\"name\":\"Hero, full width image\",\"description\":\"A hero with a full width image, heading, short paragraph and button.\",\"categories\":[\"banner\"]},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover alignfull is-light has-custom-content-position is-position-bottom-center\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50);min-height:840px\"><img class=\"wp-block-cover__image-background wp-image-10 size-full\" alt=\"\" src=\"http://localhost/wordpress/wp-content/uploads/2026/08/csr3.png\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-10 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"align\":\"wide\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"fontSize\":\"xx-large\"} -->\n<h2 class=\"wp-block-heading has-text-align-left has-xx-large-font-size\"><strong>Introduction</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Digital Community Care is a Corporate Social <em>Responsibility (CSR) program that promotes digi</em>tal awareness and supports community development through technology. The program aims to improve digital skills, encourage responsible use of technology, and strengthen community engagement for a better quality of life.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"twentytwentyfive/heading-and-paragraph-with-image\",\"name\":\"Heading and paragraph with image on the right\",\"description\":\"A two-column section with a heading and paragraph on the left, and an image on the right.\",\"categories\":[\"about\"]},\"align\":\"full\",\"className\":\"is-style-section-1\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"background\":\"#87cc5e\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull is-style-section-1 has-background\" style=\"background-color:#87cc5e;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50)\"><!-- wp:columns {\"align\":\"wide\",\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|80\"}}},\"fontSize\":\"small\"} -->\n<div class=\"wp-block-columns alignwide is-style-default has-small-font-size\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:heading {\"className\":\"wp-block-heading\"} -->\n<h2 class=\"wp-block-heading\">About The Activity CSR</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\"><br><strong>The Digital Community Care CSR activity focuses on promoting digital literacy and community engagement. Participants take part in educational sessions, hands-on learning activities, and interactive discussions to improve their digital skills, increase awareness of online safety, and encourage the responsible use of technology in everyday life.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":12,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/08/CSR5.jpg\" alt=\"\" class=\"wp-image-12\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":11,\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/08/csr4.jpg\" alt=\"\" class=\"wp-image-11\" style=\"aspect-ratio:1;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"twentytwentyfive/banner-description-images-grid\",\"name\":\"Banner with description and images grid\",\"description\":\"A banner with a short paragraph, and two images displayed in a grid layout.\",\"categories\":[\"banner\",\"featured\"]},\"align\":\"full\",\"className\":\"is-style-section-2\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"background\":\"#69c548\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull is-style-section-2 has-background\" style=\"background-color:#69c548;margin-top:0;margin-bottom:0\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"blockGap\":\"var:preset|spacing|50\"}},\"layout\":{\"type\":\"grid\",\"minimumColumnWidth\":\"26rem\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|50\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"space-between\",\"justifyContent\":\"stretch\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-text-annotation\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-text-annotation\"><strong>About Sukarelawan</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"is-style-text-subtitle\"} -->\n<p class=\"is-style-text-subtitle\">The volunteers play an important role in the <strong>Digital Community Care</strong> CSR program by assisting participants, supporting event activities, and sharing digital knowledge. Their dedication and teamwork help ensure the program runs smoothly while creating a positive impact on the community.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:image {\"id\":13,\"aspectRatio\":\"16/9\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/08/sukarelawan.jpg\" alt=\"\" class=\"wp-image-13\" style=\"aspect-ratio:16/9;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:image {\"id\":14,\"aspectRatio\":\"3/4\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/08/s1.jpg\" alt=\"\" class=\"wp-image-14\" style=\"aspect-ratio:3/4;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"contact\"],\"patternName\":\"twentytwentyfive/contact-location-and-link\",\"name\":\"Contact location and link\"},\"align\":\"full\",\"className\":\"is-style-section-3\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"color\":{\"background\":\"#a4cb39\"}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull is-style-section-3 has-background\" style=\"background-color:#a4cb39;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"blockGap\":\"var:preset|spacing|40\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\",\"verticalAlignment\":\"space-between\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:100%\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textTransform\":\"uppercase\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\" style=\"text-transform:uppercase\"><h1>Volunteer Registration Form</h1><h2>Digital Community Care – CSR Program</h2><h3>Personal Information</h3><ul data-spread=\"false\"><li>Full Name:</li><li>IC/Passport Number:</li><li>Age:</li><li>Gender:</li><li>Phone Number:</li><li>Email Address:</li><li>Address:</li></ul></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"id\":27,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"wp-block-image size-large\"} -->\n<figure class=\"wp-block-image size-full size-large\"><img src=\"http://localhost/wordpress/wp-content/uploads/2026/08/sukarelawan1.jpg\" alt=\"\" class=\"wp-image-27\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Portal Program CSR', '', 'inherit', 'closed', 'closed', '', '8-revision-v1', '', '', '2026-08-01 15:44:26', '2026-08-01 15:44:26', '', 8, 'http://localhost/wordpress/?p=28', 0, 'revision', '', 0),
